    private static DataGridView Grid()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoGenerateColumns=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false};
    private static TableLayoutPanel Panel(){var p=new TableLayoutPanel(){Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,Padding=new Padding(8)};p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));p.RowStyles.Add(new RowStyle(SizeType.AutoSize));p.RowStyles.Add(new RowStyle(SizeType.Percent,100));p.RowStyles.Add(new RowStyle(SizeType.Absolute,115));return p;}
    private Button Button(string text,Action action){var b=new Button(){Text=text,AutoSize=true};b.Click+=(_,_)=>Change(action);return b;}
    public void Bind(DirectoryEditor value){editor=value;RefreshData();}
    public void RefreshData()
    {
        if(editor?.Domain is not DomainEditor d){character.Text="Open a recognized slot to read available named fields.";inventory.DataSource=null;equipment.DataSource=null;itemIds.Items.Clear();equipmentDetail.Text="";moneyApply.Enabled=false;pointsApply.Enabled=false;return;}
        object? selectedItem=itemIds.SelectedItem;        var c=d.Character();character.Text=$"Name: {UiLanguage.Data(c.Name??"Unknown")}\nHunter rank: {c.HunterRank?.ToString()??"Unknown"}    Master rank: {c.MasterRank?.ToString()??"Unknown / absent"}\nMoney: {c.Money?.ToString("N0")??"Unknown"}    Points: {c.Points?.ToString("N0")??"Unknown"}\n{editor.MoneyMirrorStatus}\nName and ranks are read-only.\nConservative changes cannot exceed original values; game maxima are unknown.\n"+string.Join("\n",c.Issues.Keys.Select(x=>x+" is unavailable for this file."));
        moneyApply.Enabled=d.CanEditMoney;pointsApply.Enabled=d.CanEditPoints;money.Maximum=d.OriginalMoneyCeiling??0;points.Maximum=d.OriginalPointsCeiling??0;money.Value=Math.Clamp(c.Money??0,0,money.Maximum);points.Value=Math.Min(c.Points??0,points.Maximum);
        itemIds.Items.Clear();foreach(uint id in d.KnownItemIds)itemIds.Items.Add(id);if(selectedItem is not null&&itemIds.Items.Contains(selectedItem))itemIds.SelectedItem=selectedItem;else if(itemIds.Items.Count>0)itemIds.SelectedIndex=0;
        RefreshItems();RefreshCategories();RefreshEquipment();
    }
    private InventoryItem ItemSelection()=>inventory.CurrentRow?.DataBoundItem as InventoryItem??throw new InvalidOperationException("Select an inventory record.");
    private void RefreshItems(){if(editor?.Domain is DomainEditor d){int? selected=(inventory.CurrentRow?.DataBoundItem as InventoryItem)?.Index;inventory.DataSource=d.Inventory("",showEmpty.Checked).Where(row=>itemFilter.Text.Length==0||$"{row.Id} 0x{row.Id:X8}".Contains(itemFilter.Text,StringComparison.OrdinalIgnoreCase)||row.Id is uint itemId&&providerNames.Matches(GameCatalogKind.Item,itemId,itemFilter.Text)).ToList();PreserveRow(inventory,selected,row=>(row as InventoryItem)?.Index);}}
    private void RefreshCategories(){refreshingCategories=true;string? selected=categoryFilter.SelectedItem as string;categoryFilter.Items.Clear();categoryFilter.Items.Add(UiLanguage.Current=="zh-CN"?"全部类别":"All categories");if(editor?.Domain is DomainEditor d)foreach(string c in d.Equipment().Where(e=>e.Id!=null&&e.Type is 1 or 2).Select(e=>providerNames.Category(e.Type==1?GameCatalogKind.Weapon:GameCatalogKind.Armor,e.Id!.Value,e.Type)).OfType<string>().Distinct().Order())categoryFilter.Items.Add(c);categoryFilter.SelectedItem=selected;if(categoryFilter.SelectedIndex<0)categoryFilter.SelectedIndex=0;refreshingCategories=false;}
    private void RefreshEquipment(){if(editor?.Domain is DomainEditor d){int? selected=(equipment.CurrentRow?.DataBoundItem as EquipmentItem)?.Index;equipment.DataSource=d.Equipment(types.SelectedIndex<=0?null:(uint)(types.SelectedIndex-1),"").Where(row=>equipmentFilter.Text.Length==0||$"{row.Id} 0x{row.Id:X8}".Contains(equipmentFilter.Text,StringComparison.OrdinalIgnoreCase)||row.Id is uint equipId&&providerNames.Matches(row.Type==1?GameCatalogKind.Weapon:GameCatalogKind.Armor,equipId,equipmentFilter.Text,row.Type)).Where(e=>categoryFilter.SelectedIndex<=0||e.Id is uint id&&providerNames.Category(e.Type==1?GameCatalogKind.Weapon:GameCatalogKind.Armor,id,e.Type)==categoryFilter.SelectedItem as string).Where(e=>showEmptyEquipment.Checked||types.SelectedIndex==1||e.Type!=0).ToList();PreserveRow(equipment,selected,row=>(row as EquipmentItem)?.Index);ShowEquipment();}}
    private static void PreserveRow(DataGridView grid,int? selected,Func<object,int?> index){if(selected is null)return;foreach(DataGridViewRow row in grid.Rows)if(index(row.DataBoundItem!)==selected){grid.CurrentCell=row.Cells[0];row.Selected=true;break;}}
    private void ShowEquipment()
    {
        if(editor?.Domain is not DomainEditor d||equipment.CurrentRow?.DataBoundItem is not EquipmentItem row){equipmentDetail.Text="";return;}
        string description=$"Record {row.Index}: {PresentationRows.TypeName(row.Type)}, numeric ID {row.Id}. \n";
        try{description+="Decoration references (draft clear/restore): "+string.Join(", ",d.DecorationIds(row.Index))+"\n";}catch(Exception e){description+=UiLanguage.Data(e.Message)+"\n";}
        if(row.Type==3)try{var t=d.Talisman(row.Index);description+=$"Pair 1: ID {t.Pairs[0].Id} / level {t.Pairs[0].Level}; Pair 2: ID {t.Pairs[1].Id} / level {t.Pairs[1].Level}\nUse the equipment draft to edit both observed skill pairs. Socket capacities remain unknown.";}catch(Exception e){description+=UiLanguage.Data(e.Message);}
        equipmentDetail.Text=description;
    }
    private void ShowSchema()
    {
        if(editor?.Domain is not DomainEditor d||equipment.CurrentRow?.DataBoundItem is not EquipmentItem row)return;
        using var form=new Form(){Text="Read-only equipment fields",Size=new Size(1000,480),StartPosition=FormStartPosition.CenterParent};var table=Grid();table.DataSource=d.EquipmentSchema(row.Index).Select(f=>new{Field=f.Label,Identifier=$"0x{f.FieldIdentifier:X8}",Tag=f.ObservedTag,Width=f.Width,Count=f.Count,Values=string.Join(", ",f.Values),Meaning=f.Meaning,Status=f.Status}).ToList();form.Controls.Add(table);UiLanguage.Attach(form);form.ShowDialog(this);
    }
    internal bool SmokeCandidateGate()
    {
        if(editor?.Domain is not DomainEditor d)return false;uint id=d.Inventory().First(i=>i.Quantity>0).Id!.Value;var testCatalog=new GameCatalog([new(GameCatalogKind.Item,id,new(){["en"]="SYNTHETIC CANDIDATE",["zh-CN"]="合成候选"},Origin:new("SYNTHETIC TEST","CC0 synthetic labels"),DeclaredStatus:CatalogItemStatus.VERIFIED_ITEM)]);AddProvider(new LocalGameCatalogProvider(testCatalog));SetCandidateDisplay(false);bool raw=names.Label(CatalogNamespace.Item,id)==$"Item {id}";string selected=SmokeSelectionIdentity();int value=d.Character().Money!.Value;editor.SetMoney(value-1);int staged=editor.StagedCount;SetCandidateDisplay(true);bool marked=names.Label(CatalogNamespace.Item,id).Contains("candidate")||names.Label(CatalogNamespace.Item,id).Contains("候选");SetCandidateDisplay(false);bool preserved=editor.StagedCount==staged&&d.Character().Money==value-1&&selected==SmokeSelectionIdentity();editor.Undo();return raw&&marked&&preserved;
    }
    internal string SmokeSelectionIdentity()=>$"{(inventory.CurrentRow?.DataBoundItem as InventoryItem)?.Index}/{(equipment.CurrentRow?.DataBoundItem as EquipmentItem)?.Index}/{itemIds.SelectedIndex}";
    internal bool SmokeReviewLocalization()
    {
        if(editor?.Domain is not DomainEditor d)return false;
        UiLanguage.Set("en",false);RefreshData();foreach(DataGridViewRow row in equipment.Rows)if(row.DataBoundItem is EquipmentItem e&&e.Type==3){equipment.CurrentCell=row.Cells[0];break;}
        d.SetMoney(1500);int staged=editor.StagedCount;string selection=SmokeSelectionIdentity();UiLanguage.Set("zh-CN",false);
        bool translated=equipmentDetail.Text.Contains("装饰珠引用")&&equipmentDetail.Text.Contains("装备草稿")&&categoryFilter.Items[0]?.ToString()=="全部类别";
        bool preserved=selection==SmokeSelectionIdentity()&&editor.StagedCount==staged;
        UiLanguage.Set("en",false);bool restored=equipmentDetail.Text.Contains("Decoration references")&&categoryFilter.Items[0]?.ToString()=="All categories";AddProvider(new LocalGameCatalogProvider(new GameCatalog([new(GameCatalogKind.Weapon,101,new(){["en"]="SYNTHETIC"},Category:"synthetic-category",EquipmentKind:1,Origin:new("synthetic","synthetic"))])));SetCandidateDisplay(true);categoryFilter.SelectedItem="synthetic-category";string categorySelection=SmokeSelectionIdentity();UiLanguage.Set("zh-CN",false);bool categoryRetained=categoryFilter.SelectedItem?.ToString()=="synthetic-category"&&categorySelection==SmokeSelectionIdentity()&&editor.StagedCount==staged;equipmentFilter.Text="NO_SYNTHETIC_MATCH_999";bool emptyCleared=equipment.Rows.Count==0&&equipmentDetail.Text.Length==0;equipmentFilter.Clear();editor.Clear();return translated&&preserved&&restored&&categoryRetained&&emptyCleared;
    }
    internal bool SmokeSelectionRetention()
    {
        if(editor?.Domain is not DomainEditor d)return false;
        foreach(DataGridViewRow row in equipment.Rows)if(row.DataBoundItem is EquipmentItem e&&e.Type==3){equipment.CurrentCell=row.Cells[0];break;}
        if(equipment.CurrentRow?.DataBoundItem is not EquipmentItem selected)return false;
        using(var draft=new EquipmentDraftForm(editor,selected.Index,providerNames)){draft.ClearDraft();draft.ApplyDraft();}
        RefreshData();bool retained=equipment.CurrentRow?.DataBoundItem is EquipmentItem after&&after.Index==selected.Index&&d.DecorationIds(selected.Index).All(id=>id==0);editor.Undo();RefreshData();return retained;
    }
    private Button ModalButton(string text,Func<Form> create){var button=new Button(){Text=text,AutoSize=true};button.Click+=(_,_)=>{try{using var form=create();if(form.ShowDialog(this)==DialogResult.OK){RefreshData();changed();}}catch(Exception e){UiLanguage.Message(this,UiLanguage.Data(e.Message),"Change not staged",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};return button;}
    internal IReadOnlyList<object> SmokeActionLayout()
    {
        var rows=new List<object>();void Walk(Control parent){foreach(Control c in parent.Controls){if(c is Button&&c.Visible){var p=c.Parent!;rows.Add(new{text=c.Text,fullyInsideParent=c.Top>=0&&c.Bottom<=p.ClientSize.Height&&c.Left>=0&&c.Right<=p.ClientSize.Width,bounds=c.Bounds.ToString(),parentSize=p.ClientSize.ToString()});}Walk(c);}}Walk(this);return rows;
    }
    private void Change(Action action){try{action();RefreshData();changed();}catch(Exception e){UiLanguage.Message(this,UiLanguage.Data(e.Message),"Change not staged",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
